  "n.act1.a": [N, "narrator/batch1/n.act1.a.mp3", "他走進了魔法花園。花香香的。"],
  "n.act1.b": [N, "narrator/batch1/n.act1.b.mp3", "花園的燈，我先點好了。"],
  "n.act2.a": [N, "narrator/batch1/n.act2.a.mp3", "往上，是燈籠書庫。書在發光。"],
  "n.act2.b": [N, "narrator/batch1/n.act2.b.mp3", "書庫好安靜，書在說悄悄話。"],
  "n.act3.a": [N, "narrator/batch1/n.act3.a.mp3", "再往上，是星空觀星台。"],
  "n.act3.b": [N, "narrator/batch1/n.act3.b.mp3", "好高了。抬頭，就是星星。"],
  "n.boss.near.a": [N, "narrator/batch1/n.boss.near.a.mp3", "前面，有個大守衛在睡覺。"],
  "n.boss.near.b": [N, "narrator/batch1/n.boss.near.b.mp3", "樓梯上，傳來好大的呼嚕聲。"],
  "n.boss.poof": [N, "narrator/batch1/n.boss.poof.mp3", "大守衛暈了，變成滿天音符。"],
  "n.boss1.in": [N, "narrator/batch1/n.boss1.in.mp3", "塔守護獸醒了，只記得要擋路。"],
  "n.boss1.ph": [N, "narrator/batch1/n.boss1.ph.mp3", "守護獸打了個大噴嚏！"],
  "n.boss2.in": [N, "narrator/batch1/n.boss2.in.mp3", "雙翼監守醒了，要大家安靜。"],
  "n.boss2.ph": [N, "narrator/batch1/n.boss2.ph.mp3", "牠拍起翅膀，書都飛起來了。"],
  "n.boss3.in": [N, "narrator/batch1/n.boss3.in.mp3", "終焉王醒了，戴好他的王冠。"],
  "n.boss3.ph": [N, "narrator/batch1/n.boss3.ph.mp3", "王冠歪了，大王有點急了。"],
  "n.camp.rest": [N, "narrator/batch1/n.camp.rest.mp3", "他坐在營火旁，暖暖的。"],
  "n.camp.up": [N, "narrator/batch1/n.camp.up.mp3", "他把一張牌，練得更亮了。"],
  "n.clear.a": [N, "narrator/batch1/n.clear.a.mp3", "這一層的燈，全亮了。"],
  "n.clear.b": [N, "narrator/batch1/n.clear.b.mp3", "往上的樓梯，我點好燈了。"],
  "n.faint.a": [N, "narrator/batch1/n.faint.a.mp3", "累了，就躺一下吧。塔會等。"],
  "n.faint.b": [N, "narrator/batch1/n.faint.b.mp3", "頭好暈，他躺下來休息。"],
  "n.fight.big.a": [N, "narrator/batch1/n.fight.big.a.mp3", "好大一擊！燈都晃了。"],
  "n.fight.big.b": [N, "narrator/batch1/n.fight.big.b.mp3", "這一下，好響！"],
  "n.fight.block": [N, "narrator/batch1/n.fight.block.mp3", "全擋住了，穩穩的。"],
  "n.fight.elite": [N, "narrator/batch1/n.fight.elite.mp3", "一個好強的守衛，醒了。"],
  "n.fight.rk.big": [N, "narrator/batch1/n.fight.rk.big.mp3", "他聽準了，一擊！"],
  "n.fight.ry.spend": [N, "narrator/batch1/n.fight.ry.spend.mp3", "星座亮起來，滿屋都亮了。"],
  "n.fight.ry.ten": [N, "narrator/batch1/n.fight.ry.ten.mp3", "十顆星，連成星座了！"],
  "n.hero.rk": [N, "narrator/batch1/n.hero.rk.mp3", "那天，留里克來了。他在聽。"],
  "n.hero.ry": [N, "narrator/batch1/n.hero.ry.mp3", "那天，琉來了。她在數星星。"],
  "n.lore.rk": [N, "narrator/batch1/n.lore.rk.mp3", "那支音叉，他一直帶著。"],
  "n.lore.ry": [N, "narrator/batch1b/n.lore.ry.mp3", "她的小星盤，是誰給的呢？"],
  "n.map.elite": [N, "narrator/batch1/n.map.elite.mp3", "他選了難一點的路。好勇敢。"],
  "n.map.lamp": [N, "narrator/batch1/n.map.lamp.mp3", "我替他點亮了下一盞燈。"],
  "n.map.path": [N, "narrator/batch1/n.map.path.mp3", "他選了這條路。燈跟著亮。"],
  "n.pro.1": [N, "narrator/batch1/n.pro.1.mp3", "這座塔，站了好久好久。"],
  "n.pro.2": [N, "narrator/batch1/n.pro.2.mp3", "進去的人，都在裡面睡著了。"],
  "n.pro.3": [N, "narrator/batch1/n.pro.3.mp3", "只有我醒著。我提著燈，等你。"],
  "n.rest.end.a": [N, "narrator/batch1/n.rest.end.a.mp3", "燈，我留著。下次，再一起爬。"],
  "n.rest.end.b": [N, "narrator/batch1/n.rest.end.b.mp3", "塔會等你。燈也會等你。"],
  "n.shop": [N, "narrator/batch1/n.shop.mp3", "小舖的燈，一直都亮著。"],
  "n.start.again": [N, "narrator/batch1/n.start.again.mp3", "又有人來了。我把燈點亮。"],
  "n.thanks": [N, "narrator/batch1/n.thanks.mp3", "謝謝你，一路陪著他。"],
  "n.top": [N, "narrator/batch1/n.top.mp3", "他爬完了這一趟。燈全亮了。"],
  "n.wake.1": [N, "narrator/batch1/n.wake.1.mp3", "花園裡睡著的人，醒了一個。"],
  "n.wake.2": [N, "narrator/batch1/n.wake.2.mp3", "書庫裡，又醒了兩個人。"],
  "n.wake.3": [N, "narrator/batch1/n.wake.3.mp3", "星星下，三個人揉揉眼睛。"],
  "n.wake.camp": [N, "narrator/batch1/n.wake.camp.mp3", "營火旁，有人睡得好甜。"],
  "n.wake.more": [N, "narrator/batch1/n.wake.more.mp3", "醒來的人，越來越多了。"],
  "n.wake.stir": [N, "narrator/batch1/n.wake.stir.mp3", "角落裡，有人翻了個身。"],
  "n.wake.yawn": [N, "narrator/batch1/n.wake.yawn.mp3", "有人打了個哈欠，就要醒了。"],
  "n.win.a": [N, "narrator/batch1/n.win.a.mp3", "守衛都變成音符了。"],
  "n.win.b": [N, "narrator/batch1/n.win.b.mp3", "又亮了一盞燈。"],
  "n.win.c": [N, "narrator/batch1/n.win.c.mp3", "這一場，打完了。往上走。"],
  "n.win.elite": [N, "narrator/batch1/n.win.elite.mp3", "好強的守衛，也暈了。"],
